// ── Validate & Prepare ──────────────────────────────────────────
const b = $input.first().json.body ?? $input.first().json;

for (const f of ['restaurant_name', 'owner_name', 'owner_email']) {
  if (!b[f] || String(b[f]).trim() === '') throw new Error(`Missing required field: ${f}`);
}
if (!/^[^@]+@[^@]+\.[^@]+$/.test(b.owner_email)) throw new Error('Invalid email address');

// Solo para saber qué plan mostrarle más adelante en el panel — el registro
// en sí no cobra nada, restaurant-onboard le da el trial de 30 días por
// defecto (columna trial_ends_at).
const PLANS = ['basico', 'pro', 'ia'];
const plan = PLANS.includes(b.plan) ? b.plan : 'pro';

const chars = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKMNPQRSTUVWXYZ23456789';
let password = '';
for (let i = 0; i < 12; i++) password += chars[Math.floor(Math.random() * chars.length)];

return [{ json: {
  restaurant_name: String(b.restaurant_name).trim(),
  owner_name:      String(b.owner_name).trim(),
  owner_email:     String(b.owner_email).trim().toLowerCase(),
  phone:           b.phone ? String(b.phone).trim() : null,
  plan,
  password,
}}];
